//! The world generator (HQ 3.0): one seed, one 2 km world, shared by every
//! feature that needs a map -- Arena City first, anything later.
//!
//! A world is `<seed>@<version>` (Arena City is `claude-hq@1`), generated by a
//! pipeline of pure stages, each with its own sub-seed:
//!
//!   terrain (base) -> city grid, blocks, districts, lots, sites
//!     -> roads (city streets and avenues; a highway per gate and the ring,
//!        split into junctions wherever they meet)
//!     -> terrain edits applied -> highways and ring graded, every road carved
//!        into the land -> lots and sites re-seated on the final ground
//!     -> district map
//!
//! Version 2 (`claude-hq@2`, the Commons; `user:<uuid>@2`, a personal island)
//! swaps the grid for an organic city (see organic/): arterials traced through a
//! tensor field, local streets grown between them, blocks as the faces of the road
//! graph, lots split from the blocks. Highways, the ring and the rest of the
//! pipeline are shared, so version 1 is untouched. Version 2 adds the civic sites
//! (civic.rs: services on lots taken before the HQ pool, then the dock and port on the
//! river and the airport once the highways are laid), the industry zones (zones.rs) and the bus
//! and tram lines (transit.rs). Both version 2 worlds are islands (island.rs): a
//! seeded coast with the sea round it (shaped into the base terrain), the highways
//! ending at the ring, and a personal city generated at full size once, every lot,
//! site, road and transit line given the first city tier it exists in. And both have a
//! river (river.rs): from the sea to a harbour basin in town, carved into the land
//! before any street grows, bridged by the arterials and the graded roads, the dock on
//! its bank near the plaza and the port on its basin.
//!
//! Layout (where roads, blocks, lots and sites are) comes from the seed and the
//! profile only; terrain edits change heights, never layout. The result is a
//! WorldDoc of plain data layers; features read the layers they need. Every
//! layer is hashed, so a client knows what changed and caches the rest.
//!
//! Integer arithmetic throughout (positions in cm, Q16 noise, no trig): the same
//! world id and edits give a byte-identical document on every platform.

pub mod city;
pub mod civic;
pub mod districts;
pub mod island;
pub mod noise;
pub mod organic;
pub mod profile;
pub mod river;
pub mod rng;
pub mod roads;
pub mod terrain;
pub mod transit;
pub mod zones;

#[cfg(test)]
mod tests;

use serde::Serialize;

pub use terrain::Edit;

/// The generator's versions. Add one when a change would alter an existing
/// world, and keep the old behaviour reachable: things are stored against a
/// world id (lots, maps, scores), so `claude-hq@1` must keep generating the
/// same world forever. 1 is the grid city, 2 the organic one.
pub const VERSION: [u32; 2] = [1, 2];

/// The profile a world id's seed and version select: the grid city at @1; at @2
/// a personal island for a `user:` seed, else the Commons.
pub fn profile_for(seed: &str, version: u32) -> profile::Profile {
    match version {
        1 => profile::city(),
        _ if seed.starts_with("user:") => profile::island(),
        _ => profile::commons(),
    }
}

#[derive(Serialize)]
pub struct WorldDoc {
    pub id: String,
    pub seed: String,
    pub version: u32,
    pub profile: &'static str,
    pub size_cm: i64,
    pub layers: Layers,
    /// FNV-1a 64 of each layer's JSON, and of the edits applied.
    pub hashes: Hashes,
}

#[derive(Serialize)]
pub struct Layers {
    pub terrain: terrain::Terrain,
    pub districts: districts::Districts,
    pub roads: roads::Roads,
    pub blocks: Vec<city::Block>,
    pub lots: Vec<city::Lot>,
    pub sites: Vec<city::Site>,
    /// Organic worlds (@2): the industry zones and the transit lines.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub zones: Option<Vec<zones::Zone>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transit: Option<transit::Transit>,
    /// Island worlds (@2): the coast, the sea, the docks and the growth tiers' radii.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub island: Option<island::Island>,
    /// Organic worlds (@2): the river, from the sea to its harbour basin.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub river: Option<river::River>,
}

#[derive(Serialize, Debug, PartialEq)]
pub struct Hashes {
    pub terrain: String,
    pub districts: String,
    pub roads: String,
    pub blocks: String,
    pub lots: String,
    pub sites: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transit: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub island: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub river: Option<String>,
    pub edits: String,
    /// Of all the above: the world's one fingerprint.
    pub world: String,
}

/// Split `seed@version`.
pub fn parse_id(id: &str) -> Result<(&str, u32), String> {
    let (seed, ver) = id.rsplit_once('@').ok_or("a world id is <seed>@<version>")?;
    if seed.is_empty() || seed.len() > 64 || !seed.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_' || b == b':') {
        return Err("a seed is 1-64 letters, digits, '-', '_' or ':'".into());
    }
    let v: u32 = ver.parse().map_err(|_| "the version must be a number")?;
    if !VERSION.contains(&v) {
        return Err(format!("unknown generator version {v} (this server generates {VERSION:?})"));
    }
    Ok((seed, v))
}

fn hash<T: Serialize>(v: &T) -> String {
    format!("{:016x}", rng::fnv1a64(&serde_json::to_vec(v).expect("layers serialise")))
}

/// Generate world `id` (e.g. "claude-hq@1") with `edits` applied to its terrain.
pub fn generate(id: &str, edits: &[Edit]) -> Result<WorldDoc, String> {
    let (seed_str, version) = parse_id(id)?;
    let seed = rng::fnv1a64(seed_str.as_bytes());
    let p = profile_for(seed_str, version);

    let river = river::River::new(seed, &p)?;
    let base = terrain::generate_with(seed, &p, river.as_ref());
    let (mut city, mut roads, districts) = if version == 1 {
        let city = city::generate(seed, &p, &base)?;
        let roads = roads::generate(seed, &p, &base, &city.blocks)?;
        let districts = districts::generate(seed, &p, &base, &city.blocks);
        (city, roads, districts)
    } else {
        organic::generate(seed, &p, &base, river.as_ref())?
    };
    let (zones, transit, island) = if version == 1 {
        (None, None, None)
    } else {
        let coast = island::Coast::new(seed, &p);
        if coast.is_some() {
            island::trim(&mut roads);
        }
        civic::outside(&p, &base, &roads, &mut city, river.as_ref());
        // a personal island's first bus loop keeps to its tier-2 town (20 m in from the ring)
        let inner = (p.name == "island").then(|| island::RADII_CM[1] - 2_000);
        let mut transit = transit::generate(&roads, &city.sites, &city.lots, inner);
        let island = coast.map(|c| island::grow(&p, &c, &mut roads, &mut city, &mut transit));
        (Some(zones::layer(seed, &city.blocks)), Some(transit), island)
    };

    let mut terrain = base;
    terrain.apply(edits)?;
    roads.seat(&terrain, &p)?;
    roads.carve(&mut terrain);
    city.seat(&terrain);

    let layers = Layers { terrain, districts, roads, blocks: city.blocks, lots: city.lots, sites: city.sites, zones, transit, island, river };
    let mut hashes = Hashes {
        terrain: hash(&layers.terrain),
        districts: hash(&layers.districts),
        roads: hash(&layers.roads),
        blocks: hash(&layers.blocks),
        lots: hash(&layers.lots),
        sites: hash(&layers.sites),
        transit: layers.transit.as_ref().map(hash),
        island: layers.island.as_ref().map(hash),
        river: layers.river.as_ref().map(hash),
        edits: hash(&edits),
        world: String::new(),
    };
    hashes.world = hash(&hashes);
    Ok(WorldDoc { id: format!("{seed_str}@{version}"), seed: seed_str.to_string(), version, profile: p.name, size_cm: p.size_cm, layers, hashes })
}
